 void leave(){try{capture();if(draft.toString().equals(savedSnapshot)){list();return;}}catch(Exception ignored){}new AlertDialog.Builder(this).setMessage("لديك تغييرات في عرض السعر").setPositiveButton("حفظ والعودة",(d,w)->{try{capture();store.saveQuote(draft);list();}catch(Exception e){error(e);}}).setNeutralButton("متابعة التحرير",null).setNegativeButton("تجاهل التغييرات",(d,w)->list()).show();}
