 void base(String title){ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setLayoutDirection(android.view.View.LAYOUT_DIRECTION_RTL);body.setPadding(24,42,24,30);body.setBackgroundColor(0xfff6f7fb);scroll.addView(body);setContentView(scroll);body.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=i.getInsets(android.view.WindowInsets.Type.systemBars());top=bars.top;bottom=bars.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}v.setPadding(24,top+16,24,bottom+16);return i;});label(title,24);}
